-- ============================================================================
-- Pucará Turismo — carga masiva de la temporada
--
-- 23 viajes sacados de los flyers de la carpeta destinos_pucara.
-- Se puede volver a importar las veces que haga falta: usa ON DUPLICATE KEY
-- UPDATE, asi que actualiza los que ya estan en vez de duplicarlos.
--
-- Importar en phpMyAdmin: elegi la base, pestaña Importar, subi este archivo.
-- ============================================================================

SET NAMES utf8mb4;

-- ── 1. Columna de categoria ────────────────────────────────────────────────
-- Agrupa el listado de la web: por mes, verano 27, fin de año o recital.
-- El IF evita el error si ya existe de una importacion anterior.
SET @existe := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pt_paquetes' AND COLUMN_NAME = 'categoria'
);
SET @sentencia := IF(@existe = 0,
  "ALTER TABLE pt_paquetes ADD COLUMN categoria VARCHAR(20) NOT NULL DEFAULT 'mes' AFTER tags",
  'SELECT 1');
PREPARE p FROM @sentencia; EXECUTE p; DEALLOCATE PREPARE p;

-- ── 2. Los viajes ──────────────────────────────────────────────────────────
INSERT INTO pt_paquetes
  (id, slug, titulo, tipo, destino, duracion_dias, duracion_noches, precio_base, gastos_admin, suplemento_single, coche_cama_extra, descripcion_corta, descripcion_larga, incluye, no_incluye, imagen_principal, imagenes, rating, reviews, cupos_por_salida, proxima_salida, frecuencia_salidas, tags, itinerario, puntos_de_subida, politicas, categoria, activo)
VALUES
('pkg-201', 'san-bernardo-hostal-del-sol-24-31oct', 'San Bernardo — Hostal del Sol Resort & Spa ★★★★ · 24 y 31 de octubre', 'viaje_completo', 'san-bernardo', 2, 1, 135000, 10000, 0, 10000, 'Fin de semana en San Bernardo con alojamiento en el Hostal del Sol Resort & Spa ★★★★, con pileta climatizada, gimnasio y desayuno buffet.', 'Escapada de sábado y domingo a San Bernardo. Te alojás en el Hostal del Sol Resort & Spa ★★★★, que tiene pileta climatizada, gimnasio, sala de juegos y cancha de fútbol y básquet. El desayuno es buffet. Viajamos en bus mix con servicio a bordo. El segundo día aprovechás la playa hasta que emprendemos el regreso a Buenos Aires por la tarde.', '["Bus mix con servicio a bordo","1 noche en Hostal del Sol Resort & Spa ★★★★","Desayuno buffet","Pileta climatizada, gimnasio y sala de juegos","Cancha de fútbol y básquet","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hostal-del-sol-1.jpg', '["/hostal-del-sol-1.jpg","/hostal-del-sol-2.jpg","/hostal-del-sol-3.jpg","/hostal-del-sol-4.jpg"]', 4.8, 0, 30, '2026-10-24', 'semanal', '["playa","fin de semana","costa atlántica"]', '["Salida por la noche desde los puntos de subida del Gran Buenos Aires en bus mix con servicio a bordo.","Llegada a San Bernardo y desayuno buffet en el hotel. Día libre de playa.","Segundo día de playa y regreso a Buenos Aires por la tarde."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-202', 'termas-san-jose-full-day-25oct', 'Termas de San José — Full Day · 25 de octubre', 'full_day', 'colon-entre-rios', 1, 0, 99000, 10000, 0, 10000, 'Full day a las Termas de San José, en Colón, con desayuno y merienda a bordo, entrada y traslado incluidos.', 'Un día completo en las Termas de San José, en Colón, Entre Ríos. Salimos temprano desde el Gran Buenos Aires en bus semi cama con servicio a bordo, con desayuno y merienda a bordo. La entrada al complejo termal y el traslado están incluidos, y un coordinador acompaña al grupo durante toda la jornada.', '["Bus semi cama con servicio a bordo","Desayuno","Merienda a bordo","Entrada a Termas de San José","Traslado al complejo termal","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/termas-san-jose-1.jpg', '["/termas-san-jose-1.jpg","/termas-san-jose-2.jpg","/termas-san-jose-4.jpg","/termas-san-jose-5.jpg"]', 4.8, 0, 30, '2026-10-25', 'mensual', '["termas","full day","litoral"]', '["Salida temprano desde los puntos de subida del Gran Buenos Aires. Desayuno a bordo.","Llegada a Colón y día completo en las Termas de San José.","Merienda a bordo y regreso a Buenos Aires por la noche."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{"precioAnterior":110000}', 'mes', 1),
('pkg-203', 'termas-villa-elisa-full-day-25oct', 'Termas de Villa Elisa — Full Day · 25 de octubre', 'full_day', 'villa-elisa-entre-rios', 1, 0, 110000, 10000, 0, 10000, 'Full day a las Termas de Villa Elisa, con entrada y traslado, desayuno y merienda a bordo.', 'Día completo en el parque termal de Villa Elisa, uno de los más grandes de Entre Ríos, con piscinas al aire libre y climatizadas y mucho verde alrededor. Viajamos en bus semi cama con servicio a bordo, con desayuno y merienda a bordo, y la entrada y el traslado al complejo están incluidos.', '["Bus semi cama con servicio a bordo","Desayuno","Merienda a bordo","Entrada a las Termas de Villa Elisa","Traslado al complejo termal","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/villa-elisa-1.jpg', '["/villa-elisa-1.jpg","/villa-elisa-2.jpg","/villa-elisa-3.jpg"]', 4.8, 0, 30, '2026-10-25', 'mensual', '["termas","full day","litoral"]', '["Salida temprano desde los puntos de subida del Gran Buenos Aires. Desayuno a bordo.","Llegada a Villa Elisa y día completo en el parque termal.","Merienda a bordo y regreso a Buenos Aires por la noche."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{"precioAnterior":125000}', 'mes', 1),
('pkg-204', 'termas-colon-full-day-25oct', 'Termas de Colón — Full Day con almuerzo · 25 de octubre', 'full_day', 'colon-entre-rios', 1, 0, 115000, 10000, 0, 10000, 'Full day a las Termas de Colón con desayuno, almuerzo y merienda a bordo, entrada y traslado incluidos.', 'Día completo en las Termas de Colón, sobre el río Uruguay, con piscinas termales al aire libre y cubiertas y toboganes para los chicos. Es el full day más completo: incluye desayuno, almuerzo y merienda a bordo, además de la entrada y el traslado al complejo. Viajamos en bus semi cama con servicio a bordo y coordinador.', '["Bus semi cama con servicio a bordo","Desayuno","Almuerzo","Merienda a bordo","Entrada a las Termas de Colón","Traslado al complejo termal","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/termas-colon-1.jpg', '["/termas-colon-1.jpg","/termas-colon-2.jpg"]', 4.8, 0, 30, '2026-10-25', 'mensual', '["termas","full day","litoral"]', '["Salida temprano desde los puntos de subida del Gran Buenos Aires. Desayuno a bordo.","Llegada a Colón, día completo en el complejo termal y almuerzo.","Merienda a bordo y regreso a Buenos Aires por la noche."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{"precioAnterior":130000}', 'mes', 1),
('pkg-205', 'colon-san-jose-cena-show-07nov', 'Colón — Hotel Termas y Río + Cena Show · 7 de noviembre', 'viaje_completo', 'colon-entre-rios', 2, 1, 175000, 10000, 0, 10000, 'Dos días en Colón con media pensión, cena show y entrada a las Termas de San José incluida.', 'Escapada de dos días a Colón, Entre Ríos. Te alojás en el Hotel Termas y Río, a 100 metros del complejo termal y 200 de la playa del río, con media pensión y una cena show. La entrada a las Termas de San José está incluida. Viajamos en bus semi cama con coordinador. El segundo día emprendemos el regreso a Buenos Aires a las 17:00 desde las termas.', '["Bus semi cama con servicio a bordo","1 noche en Hotel Termas y Río","Media pensión","Cena show","Entrada a Termas de San José","Traslado al complejo termal","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hotel-termas-rio-1.jpg', '["/hotel-termas-rio-1.jpg","/hotel-termas-rio-2.jpg","/hotel-termas-rio-3.jpg"]', 4.8, 0, 30, '2026-11-07', 'mensual', '["termas","cena show","litoral"]', '["Salida desde los puntos de subida del Gran Buenos Aires en bus semi cama.","Llegada a Colón, check in en el Hotel Termas y Río y tarde libre. A la noche, cena show.","Día en las Termas de San José y regreso a Buenos Aires a las 17:00."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-206', 'tandil-full-day-07nov', 'Tandil — Full Day con guía local · 7 de noviembre', 'full_day', 'tandil', 1, 0, 95000, 10000, 0, 10000, 'Full day a Tandil con guía local: Cerro Centinela, Monte Calvario, Parque Independencia, Castillo Morisco, Dique del Fuerte y Piedra Movediza.', 'Un día completo recorriendo Tandil con guía local. Visitamos el Cerro Centinela, el Monte Calvario, el lago y el Parque Independencia con su Castillo Morisco, el Dique del Fuerte y la Piedra Movediza, y paramos en un regional para llevarse quesos y salames. Viajamos en bus mix con coordinador y merienda a bordo.', '["Bus mix con servicio a bordo","Guía local durante el recorrido","Merienda a bordo","Cerro Centinela y Monte Calvario","Parque Independencia y Castillo Morisco","Dique del Fuerte y Piedra Movediza","Parada en regional","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/tandil-1.jpg', '["/tandil-1.jpg","/tandil-3.jpg","/tandil-4.jpg","/tandil-5.jpg"]', 4.8, 0, 30, '2026-11-07', 'mensual', '["sierra","full day","excursión"]', '["Salida temprano desde los puntos de subida del Gran Buenos Aires.","Llegada a Tandil y recorrido con guía local por los puntos clásicos de la ciudad.","Parada en regional, merienda a bordo y regreso a Buenos Aires por la noche."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-207', 'mar-del-plata-riazor-nov', 'Mar del Plata — Hotel Riazor con pensión completa · 7, 14 y 28 de noviembre', 'viaje_completo', 'mar-del-plata', 2, 1, 118000, 10000, 0, 10000, 'Dos días en Mar del Plata en el Hotel Riazor, frente al shopping, con pensión completa y show en el hotel.', 'Escapada de dos días a Mar del Plata. Te alojás en el Hotel Riazor, frente al shopping y a 400 metros del centro Güemes, con pensión completa y show en el hotel. Viajamos en bus mix con servicio a bordo y coordinador permanente. El segundo día aprovechás la ciudad y emprendemos el regreso a Buenos Aires por la tarde.', '["Bus mix con servicio a bordo","1 noche en Hotel Riazor","Pensión completa","Show en el hotel","Coordinador permanente"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hotel-riazor-1.jpg', '["/hotel-riazor-1.jpg","/hotel-riazor-2.jpg","/hotel-riazor-3.jpg","/mar-del-plata-5.jpg"]', 4.8, 0, 30, '2026-11-07', 'semanal', '["playa","fin de semana","costa atlántica"]', '["Salida por la noche desde los puntos de subida del Gran Buenos Aires.","Llegada a Mar del Plata, desayuno en el hotel y día libre. A la noche, show en el hotel.","Segundo día libre y regreso a Buenos Aires por la tarde."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-208', 'mar-del-plata-riazor-finde-largo-21nov', 'Mar del Plata — Finde largo en el Hotel Riazor · 21 de noviembre', 'viaje_completo', 'mar-del-plata', 3, 2, 175000, 10000, 0, 10000, 'Fin de semana largo en Mar del Plata, tres días en el Hotel Riazor con pensión completa y show en el hotel.', 'Aprovechá el fin de semana largo de noviembre con tres días en Mar del Plata. Te alojás en el Hotel Riazor, frente al shopping y a 400 metros del centro Güemes, con pensión completa y show en el hotel. Viajamos en bus mix con servicio a bordo y coordinador permanente.', '["Bus mix con servicio a bordo","2 noches en Hotel Riazor","Pensión completa","Show en el hotel","Coordinador permanente"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hotel-riazor-2.jpg', '["/hotel-riazor-2.jpg","/hotel-riazor-1.jpg","/hotel-riazor-4.jpg","/mar-del-plata-5.jpg"]', 4.8, 0, 30, '2026-11-21', 'mensual', '["playa","finde largo","costa atlántica"]', '["Salida por la noche desde los puntos de subida del Gran Buenos Aires.","Llegada a Mar del Plata, desayuno en el hotel y día libre.","Día completo en la ciudad y show en el hotel.","Tercer día libre y regreso a Buenos Aires por la tarde."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-209', 'san-bernardo-hostal-del-sol-21nov', 'San Bernardo — Finde largo en el Hostal del Sol ★★★★ · 21 de noviembre', 'viaje_completo', 'san-bernardo', 3, 2, 240000, 10000, 0, 10000, 'Tres días de fin de semana largo en San Bernardo, en el Hostal del Sol Resort & Spa ★★★★ con desayuno buffet.', 'Fin de semana largo de tres días en San Bernardo, alojados en el Hostal del Sol Resort & Spa ★★★★. El hotel tiene pileta climatizada, gimnasio, sala de juegos y cancha de fútbol y básquet, y el desayuno es buffet. Viajamos en bus mix con servicio a bordo.', '["Bus mix con servicio a bordo","2 noches en Hostal del Sol Resort & Spa ★★★★","Desayuno buffet","Pileta climatizada, gimnasio y sala de juegos","Cancha de fútbol y básquet","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hostal-del-sol-2.jpg', '["/hostal-del-sol-2.jpg","/hostal-del-sol-1.jpg","/hostal-del-sol-3.jpg","/san-bernardo.jpg"]', 4.8, 0, 30, '2026-11-21', 'mensual', '["playa","finde largo","costa atlántica"]', '["Salida por la noche desde los puntos de subida del Gran Buenos Aires.","Llegada a San Bernardo, desayuno buffet y día de playa.","Día completo libre para disfrutar la playa y el hotel.","Tercer día y regreso a Buenos Aires por la tarde."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-210', 'las-grutas-hotel-mareas-26nov', 'Las Grutas — Hotel Mareas ★★★ · 26 de noviembre', 'viaje_completo', 'las-grutas', 6, 3, 485000, 10000, 0, 10000, 'Seis días en Las Grutas con media pensión en el Hotel Mareas ★★★ y excursión a Viedma y Carmen de Patagones incluida.', 'Las Grutas, en Río Negro, tiene una de las mejores playas de Argentina: aguas cálidas y de un turquesa único en la costa patagónica. Te alojás en el Hotel Mareas ★★★, con pileta y a 300 metros de la playa, con media pensión. Incluye una excursión a Viedma y Carmen de Patagones. Viajamos en bus mix con servicio a bordo.', '["Bus mix con servicio a bordo","3 noches en Hotel Mareas ★★★","Media pensión","Pileta del hotel","Excursión a Viedma y Carmen de Patagones","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/las-grutas-1.jpg', '["/las-grutas-1.jpg","/las-grutas-2.jpg","/las-grutas-3.jpg"]', 4.8, 0, 30, '2026-11-26', 'mensual', '["playa","patagonia","excursión"]', '["Salida nocturna desde el Gran Buenos Aires en bus mix con servicio a bordo.","Día de viaje por la Patagonia. Llegada a Las Grutas y check in en el Hotel Mareas.","Día de playa en Las Grutas.","Excursión a Viedma y Carmen de Patagones.","Último día de playa y salida de regreso.","Llegada a Buenos Aires."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-211', 'canasvieiras-tropicanas-29nov', 'Canasvieiras — Florianópolis — Apart Hotel Tropicanas ★★★ · 29 de noviembre', 'viaje_completo', 'canasvieiras-brasil', 8, 5, 699000, 10000, 0, 40000, 'Ocho días en Canasvieiras, Florianópolis, con media pensión buffet en el Apart Hotel Tropicanas ★★★ con piletas.', 'Canasvieiras es una de las playas más elegidas del norte de Florianópolis: mar calmo, arena blanca y todos los servicios a mano. Te alojás en el Apart Hotel Tropicanas ★★★, con piletas, en régimen de media pensión con desayuno y cena buffet. Viajamos en bus mix con servicio a bordo. Se necesita documentación vigente para salir del país.', '["Bus mix con servicio a bordo","5 noches en Apart Hotel Tropicanas ★★★","Media pensión con buffet","Piletas del hotel","Coordinador durante todo el viaje"]', '["Gastos personales","Bebidas","Excursiones opcionales","Tasas e impuestos de Brasil","Asistencia al viajero"]', '/canasvieiras-2.jpg', '["/canasvieiras-2.jpg","/canasvieiras-3.jpg","/canasvieiras-1.jpg","/canasvieiras-6.jpg","/canasvieiras-4.jpg"]', 4.8, 0, 30, '2026-11-29', 'mensual', '["playa","brasil","internacional"]', '["Salida desde el Gran Buenos Aires en bus mix con servicio a bordo.","Día de viaje y cruce de frontera.","Llegada a Canasvieiras y check in en el Apart Hotel Tropicanas.","Días libres de playa en Canasvieiras, con desayuno y cena buffet en el hotel.","Último día de playa y salida de regreso.","Llegada a Buenos Aires."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
('pkg-212', 'mar-del-plata-riazor-05dic', 'Mar del Plata — Tres días en el Hotel Riazor · 5 de diciembre', 'viaje_completo', 'mar-del-plata', 3, 2, 175000, 10000, 0, 10000, 'Tres días en Mar del Plata en el Hotel Riazor, con pensión completa y show en el hotel.', 'Tres días en Mar del Plata para arrancar diciembre. Te alojás en el Hotel Riazor, frente al shopping y a 400 metros del centro Güemes, con pensión completa y show en el hotel. Viajamos en bus mix con servicio a bordo y coordinador permanente.', '["Bus mix con servicio a bordo","2 noches en Hotel Riazor","Pensión completa","Show en el hotel","Coordinador permanente"]', '["Gastos personales","Bebidas","Excursiones opcionales"]', '/hotel-riazor-3.jpg', '["/hotel-riazor-3.jpg","/hotel-riazor-1.jpg","/hotel-riazor-2.jpg","/mar-del-plata-5.jpg"]', 4.8, 0, 30, '2026-12-05', 'mensual', '["playa","costa atlántica"]', '["Salida por la noche desde los puntos de subida del Gran Buenos Aires.","Llegada a Mar del Plata, desayuno en el hotel y día libre.","Día completo en la ciudad y show en el hotel.","Tercer día libre y regreso a Buenos Aires por la tarde."]', '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]', '{}', 'mes', 1),
