UPDATE pt_paquetes SET puntos_de_subida = '["Cruce Varela","Rotonda Los Pinos","Rotonda Lavallol","Rotonda San Justo","Ciudadela (Gral. Paz)","Morón (frente al Plaza Oeste)","Moreno (Axion Ruta 23 y Acceso Oeste)","Tigre — Pacheco (Pdor. El Turista)"]';

-- ── 4. El recital que ya estaba cargado queda en su categoria ──────────────
UPDATE pt_paquetes SET categoria = 'recital'
  WHERE titulo LIKE '%Recital%' OR titulo LIKE '%Konga%';

-- ── 5. Politica general con el texto de los puntos de subida ───────────────
INSERT INTO pt_politicas (clave, valor, orden) VALUES
  ('puntosDeSubida', 'Contamos con 8 puntos de subida en el Gran Buenos Aires: Cruce Varela, Rotonda Los Pinos, Rotonda Lavallol, Rotonda San Justo, Ciudadela (Gral. Paz), Morón (frente al Plaza Oeste), Moreno (Axion Ruta 23 y Acceso Oeste) y Tigre — Pacheco (Pdor. El Turista). Los lugares de carga pueden sufrir modificaciones para un mejor servicio en el tiempo del recorrido.', 60)
